"""Reports CSV exporter. Implement export_csv to satisfy TASK.txt."""

import csv
import io


def _validate_columns(columns):
    names = list(columns)
    seen = set()
    for name in names:
        if not isinstance(name, str):
            raise ValueError("column names must be strings")
        if name in seen:
            raise ValueError("duplicate column name: %r" % (name,))
        seen.add(name)
    return names


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    names = _validate_columns(columns)

    out = io.StringIO(newline="")
    # lineterminator=\r\n forces CRLF even on platforms with a different default.
    writer = csv.writer(out, delimiter=",", quotechar='"',
                        quoting=csv.QUOTE_MINIMAL, lineterminator="\r\n",
                        doublequote=True, escapechar=None)

    writer.writerow(names)
    for row in rows:
        record = []
        for name in names:
            value = row.get(name)
            if value is None:
                record.append("")
            else:
                record.append(value)
        writer.writerow(record)

    return out.getvalue()

