"""Focused tests for reports.export.export_csv."""

import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_header_and_order(self):
        out = export_csv([{"a": 1, "b": 2}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n1,2\r\n")

    def test_column_selection_order(self):
        out = export_csv([{"a": 1, "b": 2, "c": 3}], ["c", "a"])
        self.assertEqual(out, "c,a\r\n3,1\r\n")

    def test_crlf_and_quoting(self):
        out = export_csv(
            [{"a": 'he said "hi"', "b": "line1\nline2"}], ["a", "b"]
        )
        self.assertEqual(out, 'a,b\r\n"he said ""hi""","line1\nline2"\r\n')

    def test_embedded_cr_and_commas(self):
        out = export_csv([{"a": "x\ry", "b": "p,q"}], ["a", "b"])
        self.assertEqual(out, 'a,b\r\n"x\ry","p,q"\r\n')

    def test_unicode_preserved(self):
        out = export_csv([{"a": "caf\u00e9 \U0001F600"}], ["a"])
        self.assertEqual(out, "a\r\ncaf\u00e9 \U0001F600\r\n")

    def test_missing_and_none_are_empty(self):
        out = export_csv([{"a": None}, {"b": 5}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n,\r\n,5\r\n")

    def test_non_string_values_str(self):
        out = export_csv([{"a": 3, "b": 1.5, "c": True}], ["a", "b", "c"])
        self.assertEqual(out, "a,b,c\r\n3,1.5,True\r\n")

    def test_empty_rows_gives_header_only(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "")

    def test_one_shot_iterators(self):
        out = export_csv(iter([{"a": 1}, {"a": 2}]), iter(["a"]))
        self.assertEqual(out, "a\r\n1\r\n2\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", 1])

    def test_inputs_not_mutated(self):
        rows = [{"a": 1, "b": 2}]
        cols = ["a", "b"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1, "b": 2}])
        self.assertEqual(cols, ["a", "b"])


if __name__ == "__main__":
    unittest.main()

