from reports.export import export_csv


class ExportCsvTest(unittest.TestCase):
    def test_basic(self):
        out = export_csv(
            [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}],
            ["a", "b"],
        )
        self.assertEqual(out, "a,b\r\n1,x\r\n2,y\r\n")

    def test_quoting_and_doubling(self):
        out = export_csv(
            [{"a": 'he said "hi"', "b": "line1\nline2", "c": "x,y"}],
            ["a", "b", "c"],
        )
        self.assertEqual(
            out, 'a,b,c\r\n"he said ""hi""","line1\nline2","x,y"\r\n'
        )

