        self.assertEqual(export_csv([], []), "\r\n")
        self.assertEqual(export_csv([], ["a"]), "a\r\n")
        self.assertEqual(export_csv([{}, {}], []), "\r\n\r\n\r\n")

    def test_generators(self):
        out = export_csv(iter([{"a": 1}]), iter(["a"]))
        self.assertEqual(out, "a\r\n1\r\n")

    def test_reject_duplicates_and_nonstrings(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])
        with self.assertRaises(ValueError):
            export_csv([], [1])

