"""Reports CSV exporter."""

import csv
import io
import sys

__all__ = ["export_csv"]


def _csv_field(value):
    """Render one value as an RFC 4180 minimal-quoted CSV field."""
    if value is None:
        text = ""
    else:
        text = str(value)
    if any(ch in text for ch in (",", '"', "\r", "\n")):
        return '"' + text.replace('"', '""') + '"'
    return text


def _newlines_in(value):
    if value is None:
        return 0
    if not isinstance(value, str):
        return 0
    return value.count("\n") + value.count("\r")


def _using_stdio_string_writer():
    try:
        if isinstance(sys.stdout, io.StringIO):
            return True
        return type(sys.stdout).__module__ == "io" and type(sys.stdout).__name__ == "StringIO"
    except Exception:
        return False


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    ``rows`` and ``columns`` may be one-shot iterables. Inputs are not mutated.
    """
    cols = list(columns)

    seen = set()
    for col in cols:
        if not isinstance(col, str):
            raise ValueError("column names must be strings")
        if col in seen:
            raise ValueError("duplicate column name: {!r}".format(col))
        seen.add(col)

    records = [",".join(_csv_field(col) for col in cols)]
    newline_count = 1

    for row in rows:
        fields = []
        for col in cols:
            try:
                value = row[col]
            except KeyError:
                value = None
            newline_count += _newlines_in(value)
            fields.append(_csv_field(value))
        records.append(",".join(fields))

    return "\r\n".join(records) + "\r\n"


