import unittest

from reports.export import export_csv


class ExportCsvEdgeTests(unittest.TestCase):
    def test_value_requiring_escape_still_str_conversion(self):
        out = export_csv([{"a": 123, "b": "plain"}], ["a", "b"])
        self.assertEqual(out, "a,b\r\n123,plain\r\n")

    def test_empty_string_field(self):
        self.assertEqual(export_csv([{"a": ""}], ["a"]), "a\r\n\r\n")

    def test_field_with_only_quote(self):
        self.assertEqual(export_csv([{"a": '"'}], ["a"]), 'a\r\n""""\r\n')

    def test_multiple_rows_mixed_missing(self):
        rows = [{"a": 1}, {"b": 2}, {"a": 3, "b": 4}]
        self.assertEqual(export_csv(rows, ["a", "b"]),
                         "a,b\r\n1,\r\n,2\r\n3,4\r\n")

    def test_zero_and_false_preserved(self):
        self.assertEqual(export_csv([{"a": 0, "b": False}], ["a", "b"]),
                         "a,b\r\n0,False\r\n")

    def test_column_names_special_chars(self):
        # Column names themselves contain a comma/quote -> header must be quoted.
        out = export_csv([{'a,b': 1, 'q"q': 2}], ['a,b', 'q"q'])
        self.assertEqual(out, '"a,b","q""q"\r\n1,2\r\n')

    def test_duplicate_check_before_header_write(self):
        with self.assertRaises(ValueError):
            export_csv([], ["x", "y", "x"])

    def test_columns_tuple_not_mutated(self):
        cols = ("a", "b")
        export_csv([{"a": 1, "b": 2}], cols)
        self.assertEqual(tuple(cols), ("a", "b"))


